FEET[p.feet].st + (p.clinch ? 1 : 0) + (!p.clinch && p.pw && p[p.pw] && ACT[p[p.pw]].d ? N.pwSt : 0);
/* RULES569 idea 2, THE POWER SWITCH: one punch a beat can be thrown at FULL POWER (p.pw = 'lead' or 'rear'): +1 stamina, +1 health (a light punch) or +2 (a punch of 3 or more), one step slower. Blocked or short, he is OPEN in his next moment (his guard covers nothing; the last moment of a beat carries to the first of the next). */
const full = (a) => ({ ...a, d: a.d + (a.d >= 3 ? 2 : 1), sp: a.sp + 1, full: 1 });
